      async markTeacherAttendance(attendance) {
        const existing = await db.select().from(teacherAttendance).where(
          and3(
            eq3(teacherAttendance.teacherId, attendance.teacherId),
            eq3(teacherAttendance.attendanceDate, attendance.attendanceDate)
          )
        );
        let result;
        let wasAbsentBefore = false;
        let isAbsentNow = attendance.status !== "present";
        if (existing.length > 0) {
          wasAbsentBefore = existing[0].status !== "present";
          const [updated] = await db.update(teacherAttendance).set({
            status: attendance.status,
            reason: attendance.reason,
            isFullDay: attendance.isFullDay,
            markedBy: attendance.markedBy,
            markedAt: getCurrentDateTimeIST()
          }).where(eq3(teacherAttendance.id, existing[0].id)).returning();
          result = updated;
        } else {
          const [created] = await db.insert(teacherAttendance).values(attendance).returning();
          result = created;
        }
        if (isAbsentNow && !wasAbsentBefore) {
          console.log(`[ABSENCE] Marking teacher ${attendance.teacherId} as absent on ${attendance.attendanceDate}. Processing substitutions asynchronously...`);
          setImmediate(async () => {
            try {
              const { SubstitutionService: SubstitutionService2 } = await Promise.resolve().then(() => (init_substitution(), substitution_exports));
              const substitutionService2 = new SubstitutionService2();
              console.log(`[ABSENCE SUBSTITUTION] Creating substitutions for absent teacher ${attendance.teacherId} on ${attendance.attendanceDate}`);
              await substitutionService2.createSubstitutionsForAbsence(
                attendance.teacherId,
                attendance.attendanceDate,
                attendance.schoolId,
                result.id,
                attendance.markedBy
              );
              console.log(`[ABSENCE SUBSTITUTION] Completed processing for teacher ${attendance.teacherId}`);
            } catch (substitutionError) {
              console.error("[ABSENCE SUBSTITUTION] Error creating substitutions for absence:", substitutionError);
            }
          });
        }
        if (!isAbsentNow && wasAbsentBefore) {
          console.log(`[PRESENCE] Teacher ${attendance.teacherId} marked present on ${attendance.attendanceDate}. Auto-cancelling substitutions...`);
          setImmediate(async () => {
            try {
              const { SubstitutionService: SubstitutionService2 } = await Promise.resolve().then(() => (init_substitution(), substitution_exports));
              const substitutionService2 = new SubstitutionService2();
              console.log(`[AUTO-CANCEL] Cancelling substitutions for teacher ${attendance.teacherId} on ${attendance.attendanceDate}`);
              const cancelled = await substitutionService2.autoCancelSubstitutionsForPresence(
                attendance.teacherId,
                attendance.attendanceDate
              );
              console.log(`[AUTO-CANCEL] Cancelled ${cancelled} substitution(s) for teacher ${attendance.teacherId}`);
            } catch (cancelError) {
              console.error("[AUTO-CANCEL] Error cancelling substitutions:", cancelError);
            }
          });
        }
        return result;
      }
      async markBulkTeacherAttendance(bulkData, markedBy) {
        const { teacherId, status, reason, startDate, endDate, isFullDay } = bulkData;
        const records = [];
        const teacher = await this.getTeacher(teacherId);
        if (!teacher) {
          throw new Error("Teacher not found");
        }
        const start = new Date(startDate);
        const end = new Date(endDate);
        const currentDate = new Date(start);
        const datesToProcess = [];
        while (currentDate <= end) {
          const dateString = currentDate.toISOString().split("T")[0];
          datesToProcess.push(dateString);
          try {
            const existing = await db.select().from(teacherAttendance).where(
              and3(
                eq3(teacherAttendance.teacherId, teacherId),
                eq3(teacherAttendance.attendanceDate, dateString)
              )
            );
            if (existing.length > 0) {
              const [updated] = await db.update(teacherAttendance).set({
                status,
                reason,
                isFullDay,
                leaveStartDate: startDate,
                leaveEndDate: endDate,
                markedBy,
                markedAt: getCurrentDateTimeIST()
              }).where(eq3(teacherAttendance.id, existing[0].id)).returning();
              records.push(updated);
            } else {
              const [created] = await db.insert(teacherAttendance).values({
                teacherId,
                schoolId: teacher.schoolId,
                attendanceDate: dateString,
                status,
                reason,
                leaveStartDate: startDate,
                leaveEndDate: endDate,
                isFullDay,
                markedBy
              }).returning();
              records.push(created);
            }
          } catch (error) {
            console.error(`[BULK ATTENDANCE] Failed to mark attendance for ${dateString}:`, error);
          }
          currentDate.setDate(currentDate.getDate() + 1);
        }
        console.log(`[BULK ATTENDANCE] Marked ${records.length} attendance records for teacher ${teacher.name}. Processing substitutions asynchronously...`);
        setImmediate(async () => {
          try {
            const { SubstitutionService: SubstitutionService2 } = await Promise.resolve().then(() => (init_substitution(), substitution_exports));
            const substitutionService2 = new SubstitutionService2();
            const isAbsent = status !== "present";
            if (isAbsent && startDate && endDate) {
              try {
                console.log(`[BULK SUBSTITUTION] Creating substitutions for ${teacher.name} from ${startDate} to ${endDate}`);
                const attendanceRecord = records.find((r) => r.attendanceDate === startDate);
                if (attendanceRecord) {
                  const createdSubstitutions = await substitutionService2.createSubstitutionsForLeave(
                    teacherId,
                    startDate,
                    endDate,
                    teacher.schoolId,
                    attendanceRecord.id
                  );
                  console.log(`[BULK SUBSTITUTION] Generating AI suggestions for ${createdSubstitutions.length} substitutions`);
                  for (const substitution of createdSubstitutions) {
                    try {
                      const suggestions = await substitutionService2.suggestSubstitutes(substitution.id);
                      await db.update(teacherSubstitutions).set({
                        suggestedSubstitutes: suggestions,
                        status: "suggested",
                        updatedAt: /* @__PURE__ */ new Date()
                      }).where(eq3(teacherSubstitutions.id, substitution.id));
                      console.log(`[BULK SUBSTITUTION] Generated ${suggestions.length} AI suggestions for substitution ${substitution.id}`);
                    } catch (suggestionError) {
                      console.error(`[BULK SUBSTITUTION] Error generating suggestions for substitution ${substitution.id}:`, suggestionError);
                    }
                  }
                }
              } catch (error) {
                console.error(`[BULK SUBSTITUTION] Error creating substitutions:`, error);
              }
            }
            console.log(`[BULK SUBSTITUTION] Completed processing for teacher ${teacher.name}`);
          } catch (error) {
            console.error(`[BULK SUBSTITUTION] Failed to process substitutions:`, error);
          }
        });
        return records;
      }
