      async cancelTeacherLeave(teacherId, startDate, endDate) {
        console.log(`[CANCEL LEAVE] Cancelling leave for teacher ${teacherId} from ${startDate} to ${endDate}`);
        const attendanceRecords = await db.select().from(teacherAttendance).where(
          and3(
            eq3(teacherAttendance.teacherId, teacherId),
            gte2(teacherAttendance.attendanceDate, startDate),
            lte2(teacherAttendance.attendanceDate, endDate)
          )
        );
        const attendanceIds = attendanceRecords.map((record) => record.id);
        console.log(`[CANCEL LEAVE] Found ${attendanceRecords.length} attendance records to cancel`);
        if (attendanceIds.length > 0) {
          try {
            const relatedSubstitutions = await db.select().from(teacherSubstitutions).where(inArray2(teacherSubstitutions.teacherAttendanceId, attendanceIds));
            console.log(`[CANCEL LEAVE] Found ${relatedSubstitutions.length} related substitutions to cancel`);
            if (relatedSubstitutions.length > 0) {
              const { SubstitutionService: SubstitutionService2 } = await Promise.resolve().then(() => (init_substitution(), substitution_exports));
              const substitutionService2 = new SubstitutionService2();
              await Promise.all(
                relatedSubstitutions.map(async (substitution) => {
                  try {
                    await substitutionService2.cancelSubstitution(substitution.id);
                    console.log(`[CANCEL LEAVE] Cancelled substitution ${substitution.id}`);
                  } catch (cancelError) {
                    console.error(`[CANCEL LEAVE] Error cancelling substitution ${substitution.id}:`, cancelError);
                  }
                })
              );
              console.log(`[CANCEL LEAVE] Finished cancelling ${relatedSubstitutions.length} substitutions in parallel`);
            }
          } catch (substitutionError) {
            console.error(`[CANCEL LEAVE] Error processing substitution cancellations:`, substitutionError);
          }
        }
        const deletedAttendance = await db.delete(teacherAttendance).where(
          and3(
            eq3(teacherAttendance.teacherId, teacherId),
            gte2(teacherAttendance.attendanceDate, startDate),
            lte2(teacherAttendance.attendanceDate, endDate)
          )
        ).returning();
        console.log(`[CANCEL LEAVE] Deleted ${deletedAttendance.length} attendance records`);
        return {
          deletedCount: deletedAttendance.length
        };
      }
