async function isWorkingDay(schoolId, date2) {
  try {
    const dateObj = new Date(date2);
    const dayOfWeek = dateObj.toLocaleDateString("en-US", { weekday: "long" }).toLowerCase();
    const [timetableStructure] = await db.select().from(timetableStructures).where(eq5(timetableStructures.schoolId, schoolId)).limit(1);
    if (!timetableStructure) {
      const defaultWorkingDays = ["monday", "tuesday", "wednesday", "thursday", "friday"];
      return defaultWorkingDays.includes(dayOfWeek);
    }
    const workingDays = Array.isArray(timetableStructure.workingDays) ? timetableStructure.workingDays : JSON.parse(timetableStructure.workingDays);
    return workingDays.includes(dayOfWeek);
  } catch (error) {
    console.error("Error checking working day:", error);
    const defaultWorkingDays = ["monday", "tuesday", "wednesday", "thursday", "friday"];
    const dayOfWeek = new Date(date2).toLocaleDateString("en-US", { weekday: "long" }).toLowerCase();
    return defaultWorkingDays.includes(dayOfWeek);
  }
}
